function ac(){if(!A.ctx){const C=window.AudioContext||window.webkitAudioContext;if(!C)return null;A.ctx=new C();A.m=A.ctx.createGain();A.m.gain.value=.55;A.m.connect(A.ctx.destination)}if(A.ctx.state==="suspended")A.ctx.resume();return A.ctx}
function tone(f,t,d,ty,v){const c=A.ctx;if(!c)return;const o=c.createOscillator(),g=c.createGain();o.type=ty;o.frequency.value=f;g.gain.setValueAtTime(.0001,t);g.gain.linearRampToValueAtTime(v,t+.01);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(A.m);o.start(t);o.stop(t+d+.05)}
