labels.forEach((l,i)=>{const b=document.createElement("button");b.className="mb";b.innerHTML='<span class="cu">▶</span><span>'+l+'</span>'+(sn.includes(cl(l))?'<span class="pe" title="Déjà choisi lors d’une partie précédente">👣</span>':"");b.onclick=e=>{e.stopPropagation();pick(i)};b.onmouseenter=()=>sel(i,true);m.appendChild(b)});
