async function choice(prompt,opts,id,secret){let o2=opts;if(id&&secret){const sn=SEEN[id]||[];if(opts.filter(o=>!o.dyn).every(o=>sn.includes(o.l)))o2=[...opts,{...secret,l:"✨ "+secret.l}]}
const i=await ask(prompt,o2.map(o=>o.l),id);const o=o2[i];S.b+=o.b||0;S.f+=o.f||0;if(o.p)gain(o.p);if(o.p2)gain(o.p2);if(o.w)await say(o.w[0],o.w[1]);if(o.it)for(const x of [].concat(o.it))await getItem(x);return i}
