const BGS={labo:{i:"labo",y:0,bc:"#2e3858",v:[100,156],e:[[176,214],[176,330]],c:[236,350],m:"labo"},forest:{i:"forest",y:0,bc:"#b6cdf0",v:[120,300],e:[[176,40],[176,230]],c:[104,214],m:"forest"},village:{i:"village",y:-200,bc:"#b6cdf0",v:[150,230],e:[[110,300],[150,400]],c:[236,330],m:"village"},grotte:{i:"grotte",y:0,bc:"#1c2138",v:[130,170],e:[[150,60],[150,200]],c:[110,300],m:"grotte"},boss:{i:"labo",y:0,bc:"#2e3858",v:[176,156],e:[[176,330],[176,330]],c:[236,350],m:"boss"}};
const place=(a,x,y)=>{a.style.left=x+"px";a.style.top=y+"px"};
function walkTo(a,x1,y1,ms){return new Promise(res=>{a.classList.remove("id");a.style.backgroundPositionY="0px";const x0=parseFloat(a.style.left),y0=parseFloat(a.style.top),t0=performance.now();const st=setInterval(()=>sfx("step"),400);
(function f(t){const k=Math.min(1,(t-t0)/ms);place(a,x0+(x1-x0)*k,y0+(y1-y0)*k);a.style.zIndex=(parseFloat(a.style.top)+52)|0;if(k<1)requestAnimationFrame(f);else{clearInterval(st);a.classList.add("id");res()}})(t0)})}
