function recolor(src,map){return new Promise(res=>{const im=new Image();im.onload=()=>{const c=document.createElement("canvas");c.width=im.width;c.height=im.height;const x=c.getContext("2d");x.drawImage(im,0,0);const d=x.getImageData(0,0,c.width,c.height),p=d.data;for(let i=0;i<p.length;i+=4){const m=map[p[i]+","+p[i+1]+","+p[i+2]];if(m){p[i]=m[0];p[i+1]=m[1];p[i+2]=m[2]}}x.putImageData(d,0,0);res(c.toDataURL())};im.src=src})}
