function loadImg(s){return new Promise(r=>{const i=new Image();i.onload=()=>r(i);i.src=s})}
async function endScreen(){const f=$("#fin");f.innerHTML='<canvas id="cvs" width="390" height="844"></canvas><p id="fn" style="position:absolute;left:0;right:0;top:400px;margin:0;text-align:center;font-size:34px;font-weight:600;color:#f4b860;opacity:0;transition:opacity 2.5s">Fin</p><button id="rp" class="bx" style="position:absolute;left:90px;right:90px;top:470px;height:46px;font:17px \'Pixelify Sans\',monospace;cursor:pointer;opacity:0;transition:opacity 2.5s">Rejouer</button><button id="fm" class="bx" style="position:absolute;left:90px;right:90px;top:528px;height:46px;font:17px \'Pixelify Sans\',monospace;cursor:pointer;opacity:0;transition:opacity 2.5s">Fermer le jeu</button><p id="bye" style="position:absolute;left:30px;right:30px;top:470px;margin:0;text-align:center;font-size:17px;color:#c7d0f2;opacity:0;transition:opacity 1.5s">Tu peux maintenant fermer cet onglet.</p>';
music(null);try{await document.fonts.load('600 26px "Pixelify Sans"')}catch(e){}
const [em,el,vi]=await Promise.all([loadImg(IMG.emb),loadImg(IMG.el),loadImg(IMG.vi)]);
const off=document.createElement("canvas");off.width=390;off.height=844;const o=off.getContext("2d");o.imageSmoothingEnabled=false;o.fillStyle="#000";o.fillRect(0,0,390,844);
o.drawImage(em,0,0,26,40,143,110,104,160);o.drawImage(el,18,0,18,26,66,330,108,156);o.drawImage(vi,18,0,18,26,216,330,108,156);
o.textAlign="center";o.fillStyle="#f4b860";o.font='600 28px "Pixelify Sans",monospace';o.fillText("Joyeux anniversaire",195,580);o.fillText(NAME,195,616);o.fillStyle="#fffbe8";o.font='18px "Pixelify Sans",monospace';o.fillText("On choisit la date ensemble.",195,670);
const d=o.getImageData(0,0,390,844).data,P=[];
for(let y=0;y<844;y+=3)for(let x=0;x<390;x+=3){const i=(y*390+x)*4;if(d[i]+d[i+1]+d[i+2]>60)P.push({x,y,c:"rgb("+d[i]+","+d[i+1]+","+d[i+2]+")",dl:x/390*4200+Math.random()*2600+y/844*500,vx:25+Math.random()*90,vy:50+Math.random()*150,sw:Math.random()*6})}
const cv=$("#cvs"),g=cv.getContext("2d"),t0=performance.now();sfx("comic");
await new Promise(res=>{(function fr(now){const t=now-t0;g.fillStyle="#000";g.fillRect(0,0,390,844);let left=0;
for(const p of P){if(t<p.dl){g.fillStyle=p.c;g.fillRect(p.x,p.y,3,3);left++}else{const q=(t-p.dl)/2400;if(q<1){left++;g.globalAlpha=1-q;g.fillStyle=p.c;g.fillRect(p.x+p.vx*q*2+Math.sin(q*6+p.sw)*p.sw,p.y-p.vy*q*2.2,3,3);g.globalAlpha=1}}}
if(left>0)requestAnimationFrame(fr);else res()})(t0)});
await W(600);$("#fn").style.opacity=1;await W(1500);$("#rp").style.opacity=1;$("#fm").style.opacity=1;$("#rp").onclick=()=>location.reload();$("#fm").onclick=()=>{if(A.ctx)A.ctx.suspend();$("#rp").style.display="none";$("#fm").style.display="none";$("#fn").textContent="Merci d’avoir joué";$("#fn").style.fontSize="26px";$("#bye").style.opacity=1;try{window.close()}catch(e){}}}
/* ---------- partie ---------- */
const lean=()=>S.b>=S.f+2?"A":S.f>=S.b+2?"B":"C";
async function run(){
await scene("labo","Ch. 1 · Le Labo");
await say("Victorine","Dresseuse "+NAME+" ! Tu es en retard. Enfin non, moi je suis en avance, c’est différent.");
await say("Victorine","Bienvenue au Royaume des Lanternes ! Chaque hiver, une Lumière rare s’allume quelque part dans le royaume. Personne ne sait où. La légende dit que seule une dresseuse très spéciale peut la retrouver.");
await say("Victorine","Je t’ai inscrite. Sans te demander. Désolée.");
await say("Victorine","Voici comment ça marche : tu explores, tu rencontres des habitants, tu ramasses des objets, et tu fais des choix. Il n’y a pas de mauvaise réponse. Il y a juste des conséquences.");
if(await ask("Prête ?",["Prête !","Je n’ai pas vraiment le choix, hein ?"],"pret")===1)await say("Victorine","Non.");
let i=await ask("Avant de partir, un compagnon. Choisis avec ton cœur, ou avec ton estomac.",["Salamèche","Flocon","Mousse"],"comp");
await setComp(i);await say("Victorine",["Excellent choix. Il a déjà l’air de vouloir un câlin et un goûter.","Il fond quand il est ému. Évite les scènes tristes.","Elle a un avis sur tout. Vous allez bien vous entendre."][i]);
await say("Victorine","Prends ça. Il pleut parfois dans le royaume. Et on ne sait jamais ce qu’une bonne écharpe peut devenir.");await getItem("echarpe");gain(15);
await choice("Un seul autre objet rentre dans ton sac de dresseuse. Choisis bien (ou pas).",[{l:"Une boussole bricolée",b:1,p:1,w:["Victorine","Elle indique toujours le Nord, ou la sortie du parking."],it:"boussole"},{l:"Un thermos fumant",f:1,p:3,w:["Victorine","Il ne refroidit jamais. Ne demande pas comment."],it:"thermos"},{l:"Un petit miroir de poche",p:9,w:["Victorine","Pour vérifier que tu es magnifique à chaque étape."],it:"miroir"}],"sac",{l:"Tout, d’un seul coup",b:1,f:1,p:1,w:["Victorine","Dans ce sac, tout rentre. Tout."],it:["boussole","thermos","miroir"]});
await narr("À toi de jouer ! Déplace-toi avec les flèches (ou ZQSD, ou la croix à l’écran). Appuie sur A ou sur E pour parler et ramasser ce qui brille.");
await roam("labo");
await scene("forest","Ch. 2 · La Forêt");
await narr("Une forêt sombre et enneigée, des lanternes accrochées aux branches. Les flocons tombent doucement.");
await roam("forest");
await scene("village","Ch. 3 · Village de Givre");
await narr("Des chalets en bois, des guirlandes, une odeur de pain d’épices. Un lac gelé scintille plus loin.");
await roam("village");
await say("Victorine",{A:"Tu avances vite et tu regardes loin. Une vraie exploratrice. Je sens que la Lumière est très loin d’ici.",B:"Tu t’arrêtes là où il fait chaud. Je sens que la Lumière est tout près, presque à la maison.",C:"Je n’arrive pas à te lire. Exploratrice ? Gourmande ? Les deux ? Fascinant."}[lean()]);
await scene("grotte","Ch. 4 · La Grotte");
await narr("L’air est frais, les cristaux brillent. Quelque chose rôde au fond.");
await roam("grotte");
await scene("boss","Ch. 5 · Le duel");
await say("Victorine","La Lumière est derrière ces portes, mais je dois te tester. Un duel, entre amies.");
const hp=$("#hp");let h=3;const dr=()=>{hp.style.display="block";hp.textContent="Victorine  "+"♥".repeat(h)+"♡".repeat(3-h)};dr();
const AT=[["Câlin Éclair","Victorine esquive… et se fait câliner quand même. Elle fond."],["Fou Rire","Elissa éclate de rire. Contagieux. Victorine tient bon, à peine."],["Selfie Surprise","Flash ! Victorine, éblouie, pose malgré elle."]];
while(h>0){i=await ask("À toi de jouer !",AT.map(a=>a[0]));sfx("hit");await narr(AT[i][1]);h--;dr()}
await say("Victorine","Je suis K.O.… de rire. Bravo.");hp.style.display="none";
await say("Victorine","Deux portes. À gauche, la Brume. À droite, la Braise. Une seule s’ouvre sur la Lumière.");
i=await ask("Quelle porte ouvres-tu ?",["La Porte de Brume","La Porte de Braise"],"porte");sfx("door");
if(i===0)await narr("La porte s’ouvre sur une route bordée de guirlandes. Un vent froid, une voiture qui attend.");else{await narr("La porte s’ouvre sur une table dressée, des bougies, une odeur de plat chaud.");await say("Victorine","Tu pensais trouver quelque chose de précis, hein ?")}
await say("Victorine","Je dois t’avouer quelque chose. Les deux portes mènent au même endroit.");
await say("Victorine","Tu croyais choisir. En vérité, tout t’amenait ici, depuis le Labo.");
await finale()}
